drop policy if exists "Admins can create case updates" on public.case_updates; create policy "Authorised staff can create case updates" on public.case_updates for insert to authenticated with check (admin_id = (select auth.uid()) and (public.is_super_admin((select auth.uid())) or (public.is_campus_admin((select auth.uid())) and exists (select 1 from public.incidents i where i.id = incident_id and i.campus = public.get_user_campus((select auth.uid()))))));